<?php declare(strict_types=1); namespace App\Modules\Tourism\Controllers; use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;use App\Modules\Tourism\Services\TourismTripService; final class TourismTripController extends Controller{private TourismTripService $s;private Authorization $a;public function __construct(){$this->s=new TourismTripService();$this->a=new Authorization();}public function index(){try{$this->a->authorize('tourism.trips.view');}catch(RuntimeException $e){flash('error',$e->getMessage());redirect('/tourism');return;}$this->view('Tourism::Trips.index',['title'=>'Trip Plans','trips'=>$this->s->all((int)Auth::tenantId())]);}}